/* ==== INTERFACE ====
方向：瑞士国际主义风格（Swiss Style）与高理性工程图解语言结合。依托 neuron-to-formula 宁静透亮的灰绿/鼠尾草底色（#DAE1DC）与 GridZoom 的理性米灰，融合清晰强对比的深墨绿冷黑文字、极细工程网格线、以及来自 VisualizingDitheringThreejs 的醒目钴蓝（分类正类/激活状态）与明快陶土橘红（决策边界/损失下降）作为高辨识度双色指示。排版以严格的无衬线强字阶、紧凑网格对齐、直角精密结构和直观数学图解为核心。
token --bg：#DAE1DC（低饱和鼠尾草灰绿底色，无图平涂可用）
token --text：#16201B（高对比深墨黑绿正文，确保公式与概念高清晰度）
token --font-sans："NTF-inter", "NTF-noto-sans-sc", sans-serif（通用正文、公式注记与控件）
token --font-title："NTF-barlow-condensed", "NTF-noto-sans-sc", sans-serif（紧凑强字阶标题）
token --fs-hero：72px / 行高 1.05（封面与大章节极度凝练强调）
token --fs-h1：38px / 行高 1.15（普通页题名，直立凝练）
token --fs-h2：22px / 行高 1.25（区块标题、参数面板分组、公式推导步骤名）
token --fs-lead：20px / 行高 1.45（核心导语、重点结论）
token --fs-body：16px / 行高 1.55（正文段落、算法逻辑解释）
token --fs-label：13px / 行高 1.4（参数刻度、层标签、权重与偏置标注）
token --fs-tick：11px / 行高 1.2（坐标轴刻度、图表数值微标）
class .nt-title：普通页主标题，默认 --fs-h1，字重 800，英中混排。
class .nt-lead：重要提要与定理引导，字重 500。
class .nt-label：小字号高可读性工程标注、参数说明。
class .nt-math-box：直角精密数学公式行，承载感知机/梯度下降/损失公式推导。
class .nt-controls：直角高理性交互控制条，带清晰 hover、active 与 focus-visible 键盘焦点。
class .nt-boundary-canvas / .nt-scatter-node：用于二维分类平面、样本点、决策边界的共享视觉类。
variant opening：html[data-variant="opening"]，底色转为理性深墨青（#101915），前景转为高对比象牙白（#EFF3F0），网格线转为精密冷灰，适合开篇视觉冲击；净空安全区四周各留 64px。
默认：未设 data-variant；纯色底叠加 32px 虚线工程十字网格，背景无图片资源依赖。
品牌：无。
==== /INTERFACE ==== */

/* 字体资源声明 */
@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-1.ttf");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-2.ttf");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

/* 核心变量 */
:root {
  --bg: #DAE1DC;
  --text: #16201B;
  --text-muted: #56645E;
  --text-sub: #7A8983;
  --border: #A6B4AD;
  --border-light: rgba(22, 32, 27, 0.12);

  /* 神经网络与二分类专属指示色（兼顾高辨识度与色盲友好） */
  --class-a: #3158D4;         /* 类别 A / 正向前进 / 神经元激活 */
  --class-b: #E04F2E;         /* 类别 B / 反向梯度 / 损失焦点 */
  --decision-line: #16201B;   /* 决策边界直线 / 分割曲面 */
  --accent-soft-a: rgba(49, 88, 212, 0.15);
  --accent-soft-b: rgba(224, 79, 46, 0.15);

  --focus: #3158D4;

  /* 字体族 */
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-title: "NTF-barlow-condensed", "NTF-noto-sans-sc", sans-serif;
  --font-mono: "NTF-inter", SFMono-Regular, Consolas, "Liberation Mono", Menlo, monospace;

  /* 字阶 (固定画布 1600x900) */
  --fs-hero: 72px;
  --fs-h1: 38px;
  --fs-h2: 22px;
  --fs-lead: 20px;
  --fs-body: 16px;
  --fs-sec: 14px;
  --fs-label: 13px;
  --fs-tick: 11px;

  /* 间距 */
  --sp-xs: 4px;
  --sp-sm: 8px;
  --sp-md: 16px;
  --sp-lg: 24px;
  --sp-xl: 36px;
  --sp-2xl: 48px;

  /* 图表、SVG 与 Canvas 共享属性 */
  --chart-line-width: 2px;
  --chart-axis-width: 1px;
  --node-size: 8px;
}

/* 舞台基底与默认网格 */
#stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(to right, rgba(22, 32, 27, 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(22, 32, 27, 0.04) 1px, transparent 1px);
  background-size: 32px 32px, 128px 128px, 128px 128px;
  background-position: 0 0, 0 0, 0 0;
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 变体：opening（深邃理性工程开篇） */
html[data-variant="opening"] {
  --bg: #111A16;
  --text: #EFF3F0;
  --text-muted: #8E9E96;
  --text-sub: #60736B;
  --border: #2C3D34;
  --border-light: rgba(239, 243, 240, 0.12);
  --class-a: #5C7FF4;
  --class-b: #F26949;
  --decision-line: #EFF3F0;
  --accent-soft-a: rgba(92, 127, 244, 0.2);
  --accent-soft-b: rgba(242, 105, 73, 0.2);
  --focus: #5C7FF4;
}

html[data-variant="opening"] #stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(to right, rgba(239, 243, 240, 0.03) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(239, 243, 240, 0.03) 1px, transparent 1px);
  background-size: 32px 32px, 128px 128px, 128px 128px;
}

/* 标题系统：瑞士国际主义精密排字 */
.nt-hero {
  font-family: var(--font-title);
  font-size: var(--fs-hero);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  margin: 0;
}

.nt-hero:lang(zh) {
  font-family: "NTF-noto-sans-sc", sans-serif;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.nt-title {
  font-family: var(--font-title);
  font-size: var(--fs-h1);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.01em;
  margin: 0;
  color: var(--text);
}

.nt-title:lang(zh) {
  font-family: "NTF-noto-sans-sc", sans-serif;
  font-weight: 800;
  letter-spacing: 0;
}

.nt-section-title {
  font-family: var(--font-title);
  font-size: var(--fs-h2);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text);
  margin: 0 0 var(--sp-sm) 0;
  display: flex;
  align-items: center;
  gap: var(--sp-sm);
}

.nt-section-title::before {
  content: "";
  display: inline-block;
  width: 4px;
  height: 16px;
  background-color: var(--text);
}

.nt-lead {
  font-size: var(--fs-lead);
  line-height: 1.45;
  font-weight: 500;
  color: var(--text);
  margin: 0;
}

.nt-body {
  font-size: var(--fs-body);
  line-height: 1.55;
  font-weight: 400;
  color: var(--text-muted);
  margin: 0;
}

.nt-label {
  font-size: var(--fs-label);
  line-height: 1.4;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-sub);
}

.nt-tick {
  font-family: var(--font-mono);
  font-size: var(--fs-tick);
  line-height: 1.2;
  color: var(--text-sub);
}

/* 数学推导与公式容器（结构化、可对齐） */
.nt-math-box {
  display: inline-flex;
  align-items: center;
  padding: var(--sp-xs) var(--sp-md);
  background: rgba(22, 32, 27, 0.04);
  border-left: 3px solid var(--text);
  font-family: var(--font-mono);
  font-size: var(--fs-sec);
  color: var(--text);
  gap: var(--sp-sm);
}

html[data-variant="opening"] .nt-math-box {
  background: rgba(239, 243, 240, 0.06);
  border-left-color: var(--text);
}

/* 控制栏、交互按钮与切换组件 */
.nt-controls {
  display: flex;
  align-items: center;
  gap: var(--sp-sm);
  background: rgba(22, 32, 27, 0.03);
  border: 1px solid var(--border);
  padding: var(--sp-xs) var(--sp-sm);
  border-radius: 0px;
}

.nt-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 600;
  padding: 6px 14px;
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 0px;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  user-select: none;
}

.nt-btn:hover {
  background-color: var(--text);
  color: var(--bg);
}

.nt-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.nt-btn[aria-pressed="true"],
.nt-btn.is-active {
  background-color: var(--text);
  color: var(--bg);
  border-color: var(--text);
}

/* 二维数据平面、神经网络结构与 SVG 图表通用标示 */
.nt-chart {
  display: block;
  overflow: visible;
}

.nt-chart .axis-line {
  stroke: var(--border);
  stroke-width: var(--chart-axis-width);
  shape-rendering: crispEdges;
}

.nt-chart .grid-line {
  stroke: var(--border-light);
  stroke-dasharray: 2 4;
  stroke-width: 1px;
}

.nt-chart .decision-boundary {
  stroke: var(--decision-line);
  stroke-width: var(--chart-line-width);
  fill: none;
}

.nt-chart .sample-point-a {
  fill: var(--class-a);
}

.nt-chart .sample-point-b {
  fill: var(--class-b);
}

.nt-chart .loss-curve {
  fill: none;
  stroke: var(--class-b);
  stroke-width: var(--chart-line-width);
}

.nt-chart .weight-connection {
  stroke: var(--border);
  stroke-width: 1.5px;
}

.nt-chart .weight-connection.is-forward {
  stroke: var(--class-a);
}

.nt-chart .weight-connection.is-backward {
  stroke: var(--class-b);
  stroke-dasharray: 4 2;
}

/* 紧凑指示牌与信息微标签 */
.nt-tag {
  display: inline-block;
  padding: 2px 6px;
  font-size: var(--fs-tick);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 0px;
}

.nt-tag-a {
  background-color: var(--accent-soft-a);
  color: var(--class-a);
  border: 1px solid var(--class-a);
}

.nt-tag-b {
  background-color: var(--accent-soft-b);
  color: var(--class-b);
  border: 1px solid var(--class-b);
}

/* 动效友好与无障碍偏好 */
@media (prefers-reduced-motion: reduce) {
  .nt-btn,
  .nt-chart * {
    transition: none !important;
    animation: none !important;
  }
}
